import{_ as i,o as t,c as a,a2 as e}from"./chunks/framework.DnrXFDHb.js";const c=JSON.parse('{"title":"输出类型","description":"七种输出 Sink（console、audio、midi_file、websocket、json_log、session、composite）的使用说明","frontmatter":{"title":"输出类型","description":"七种输出 Sink（console、audio、midi_file、websocket、json_log、session、composite）的使用说明"},"headers":[],"relativePath":"user-guide/output-types.md","filePath":"user-guide/output-types.md","lastUpdated":1775729555000}'),n={name:"user-guide/output-types.md"};function d(h,s,l,p,o,k){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="输出类型" tabindex="-1">输出类型 <a class="header-anchor" href="#输出类型" aria-label="Permalink to &quot;输出类型&quot;">​</a></h1><p>StreamMUSE 支持七种用户可选输出类型，通过 <code>--output-type</code> 参数指定。<code>--enable-metronome</code> 是一个额外开关，不是独立 output type。</p><hr><h2 id="console-—-控制台输出-默认" tabindex="-1">console — 控制台输出（默认） <a class="header-anchor" href="#console-—-控制台输出-默认" aria-label="Permalink to &quot;console — 控制台输出（默认）&quot;">​</a></h2><p>将事件和统计信息打印到终端，适合调试和快速验证。当前版本会自动附加 MIDI 录制，输出到 session 目录中的 <code>combined.mid</code>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> console</span></span></code></pre></div><hr><h2 id="audio-—-实时-midi-播放" tabindex="-1">audio — 实时 MIDI 播放 <a class="header-anchor" href="#audio-—-实时-midi-播放" aria-label="Permalink to &quot;audio — 实时 MIDI 播放&quot;">​</a></h2><p>将模型伴奏通过 MIDI 设备实时播放，需要系统中有 MIDI 输出端口。当前版本会自动附加 MIDI 录制。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --midi-out-port</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My Synth&quot;</span></span></code></pre></div><p>查看可用输出端口：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mido</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mido.get_output_names())</span></span></code></pre></div><hr><h2 id="midi-file-—-midi-文件录制" tabindex="-1">midi_file — MIDI 文件录制 <a class="header-anchor" href="#midi-file-—-midi-文件录制" aria-label="Permalink to &quot;midi_file — MIDI 文件录制&quot;">​</a></h2><p>将演奏录制为单个 MIDI 文件。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --input-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> midi_file</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --midi-file-output-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session.mid</span></span></code></pre></div><p>默认包含 <code>Melody</code> 和 <code>Accompaniment</code> 两个音轨。开启 <code>--enable-metronome</code> 后会额外包含 <code>Metronome</code> 鼓轨。</p><hr><h2 id="websocket-—-websocket-推送" tabindex="-1">websocket — WebSocket 推送 <a class="header-anchor" href="#websocket-—-websocket-推送" aria-label="Permalink to &quot;websocket — WebSocket 推送&quot;">​</a></h2><p>将事件序列化为 JSON 放入队列，供 WebSocket 服务器推送给前端。当前版本会自动附加 MIDI 录制。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> websocket</span></span></code></pre></div><hr><h2 id="json-log-—-json-日志" tabindex="-1">json_log — JSON 日志 <a class="header-anchor" href="#json-log-—-json-日志" aria-label="Permalink to &quot;json_log — JSON 日志&quot;">​</a></h2><p>将事件和推理记录写入 JSON 文件，用于事后分析。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json_log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span></span></code></pre></div><p>输出文件：</p><ul><li><code>events.jsonl</code>：每行一个事件</li><li><code>inferences.json</code>：推理记录</li><li><code>session_config.json</code>：会话配置快照</li></ul><p><code>json_log</code> 不自动写 <code>combined.mid</code>。</p><hr><h2 id="session-—-完整会话-midi-json" tabindex="-1">session — 完整会话（MIDI + JSON） <a class="header-anchor" href="#session-—-完整会话-midi-json" aria-label="Permalink to &quot;session — 完整会话（MIDI + JSON）&quot;">​</a></h2><p>在 JSON 日志基础上增加 MIDI 录制。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span></span></code></pre></div><p>常见输出：</p><ul><li><code>combined.mid</code>：MIDI 录制</li><li><code>events.jsonl</code>：事件日志</li><li><code>inferences.json</code>：推理日志</li><li><code>performance.json</code>：延迟与事件统计</li><li><code>statistics.csv</code>：摘要指标 CSV</li><li><code>session_summary.txt</code>：会话完成摘要</li></ul><hr><h2 id="composite-—-组合输出-推荐调试模式" tabindex="-1">composite — 组合输出（推荐调试模式） <a class="header-anchor" href="#composite-—-组合输出-推荐调试模式" aria-label="Permalink to &quot;composite — 组合输出（推荐调试模式）&quot;">​</a></h2><p>同时激活控制台输出和完整会话日志。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> composite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span></span></code></pre></div><p>CLI 中通常等价于 <code>ConsoleOutputSink + SessionLoggerOutputSink</code>。</p><hr><h2 id="metronome-输出" tabindex="-1">metronome 输出 <a class="header-anchor" href="#metronome-输出" aria-label="Permalink to &quot;metronome 输出&quot;">​</a></h2><p>开启：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --input-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> midi_file</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --midi-file-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prompts/inputs_lekai/mel/1.mid</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> console</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --enable-metronome</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --count-in-beats</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span></span></code></pre></div><p>行为：</p><ol><li>实时 MIDI click 由 <code>MetronomeOutputSink</code> 输出。</li><li>写 MIDI 的模式会额外记录 <code>Metronome</code> 鼓轨。</li><li>count-in 阶段的 click 使用负 tick，MIDI 录制会把它平移到文件开头。</li></ol><p>默认 click 参数：</p><table tabindex="0"><thead><tr><th>类型</th><th>note</th><th>velocity</th><th>channel</th></tr></thead><tbody><tr><td>downbeat</td><td>76</td><td>110</td><td>9</td></tr><tr><td>beat</td><td>77</td><td>80</td><td>9</td></tr></tbody></table><hr><h2 id="各类型特性对比" tabindex="-1">各类型特性对比 <a class="header-anchor" href="#各类型特性对比" aria-label="Permalink to &quot;各类型特性对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>实时反馈</th><th>MIDI 录制</th><th>JSON 日志</th><th>性能分析</th></tr></thead><tbody><tr><td><code>console</code></td><td>✓</td><td>✓（自动 <code>combined.mid</code>）</td><td>–</td><td>–</td></tr><tr><td><code>audio</code></td><td>MIDI 播放</td><td>✓（自动 <code>combined.mid</code>）</td><td>–</td><td>–</td></tr><tr><td><code>midi_file</code></td><td>–</td><td>✓（指定路径）</td><td>–</td><td>–</td></tr><tr><td><code>websocket</code></td><td>JSON 推送</td><td>✓（自动 <code>combined.mid</code>）</td><td>–</td><td>–</td></tr><tr><td><code>json_log</code></td><td>–</td><td>–</td><td>✓</td><td>–</td></tr><tr><td><code>session</code></td><td>–</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>composite</code></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr></tbody></table>`,50)])])}const F=i(n,[["render",d]]);export{c as __pageData,F as default};
